from collections import Counter
def tile_transform(g):
    h,w=len(g),len(g[0])
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    vcols=[j for j in range(w) if len({r[j] for r in g})==1 and g[0][j]!=bg]
    hrows=[i for i in range(h) if len(set(g[i]))==1 and g[i][0]!=bg]
    vset=set(vcols); hset=set(hrows)
    # cell boundaries
    vb=[j for j in range(w) if j not in vset]
    hb=[i for i in range(h) if i not in hset]
    # group consecutive
    def groups(idx):
        out=[];cur=[]
        for x in idx:
            if cur and x==cur[-1]+1: cur.append(x)
            else:
                if cur: out.append(cur)
                cur=[x]
        if cur: out.append(cur)
        return out
    vg,hg=groups(vb),groups(hb)
    # find pattern block: block with a cell != bg
    pat=None
    for hb_ in hg:
        for vb_ in vg:
            if any(g[i][j]!=bg for i in hb_ for j in vb_):
                pat=[[g[i][j] for j in vb_] for i in hb_]
    ph,pw=len(pat),len(pat[0])
    return [[pat[i%ph][j%pw] for j in range(w)] for i in range(h)]
